// Helpers for checks that scan source *code* for a forbidden token (a banned
// API, an impure import, a DOM specific). Such a check must see code, not
// prose: a comment or a doc-string that merely *names* `chrome.storage` or
// `fetch(` is describing the code, not doing it, and matching it is a false
// positive that fails the build over an English sentence. Strip comments first.

// Return `source` with its JS/TS comments removed, leaving everything else —
// including string and template literals — byte-for-byte intact. String-aware
// on purpose: a `//` inside "https://…" is not a comment, and dropping the rest
// of that line would corrupt real code (and could hide a genuine violation that
// follows on the same line). Regex literals are treated as code and preserved.
// Newlines inside block comments are kept so line numbers don't shift.
export function stripComments(source) {
  let out = '';
  let state = 'code'; // code | line | block | sq | dq | tpl
  for (let i = 0; i < source.length; i++) {
    const c = source[i];
    const c2 = source[i + 1];
    if (state === 'code') {
      if (c === '/' && c2 === '/') { state = 'line'; i++; continue; }
      if (c === '/' && c2 === '*') { state = 'block'; i++; continue; }
      if (c === "'") state = 'sq';
      else if (c === '"') state = 'dq';
      else if (c === '`') state = 'tpl';
      out += c;
    } else if (state === 'line') {
      if (c === '\n') { state = 'code'; out += c; }
    } else if (state === 'block') {
      if (c === '*' && c2 === '/') { state = 'code'; i++; }
      else if (c === '\n') out += c;
    } else {
      // Inside a string/template literal: copy through until the matching quote,
      // honoring backslash escapes so an escaped quote doesn't end it early.
      out += c;
      if (c === '\\') { out += c2 ?? ''; i++; }
      else if ((state === 'sq' && c === "'") || (state === 'dq' && c === '"') || (state === 'tpl' && c === '`')) {
        state = 'code';
      }
    }
  }
  return out;
}

// The extensions whose comments `stripComments` actually models. A file outside
// this set is never called comments-only: the parser cannot see its comments, so
// "nothing but comments changed" is a claim it has no grounds for, and answering
// "no" is the end that fails safe for both callers below.
export const COMMENT_CHECKABLE = new Set([
  '.mjs', '.cjs', '.js', '.jsx', '.ts', '.tsx', '.c', '.h', '.cc', '.cpp', '.hpp',
  '.java', '.go', '.swift', '.kt', '.dart', '.rs', '.cs', '.scss', '.css',
]);

// Did a change to `file` touch only its comments? `before`/`after` are the file's
// two contents, null where it was added or deleted — neither of which is a
// comment-only change, whatever the other side holds.
//
// Indentation and blank lines are ignored, so a whitespace-only edit inside a
// template literal reads as comments-only; in a language whose indentation is
// semantic the extension set above has already answered no.
//
// Its callers grant a PERMISSION on the answer — may this run land its own pull
// request unreviewed, may it have touched this file at all — which is why the safe
// end is "no" and why the answer lives here rather than in each of them.
export function commentOnly(file, before, after) {
  if (before == null || after == null) return false;
  const dot = file.lastIndexOf('.');
  const ext = dot === -1 ? '' : file.slice(dot).toLowerCase();
  if (!COMMENT_CHECKABLE.has(ext)) return false;
  const meat = (text) => stripComments(text).split('\n').map((l) => l.trim()).filter((l) => l !== '').join('\n');
  return meat(before) === meat(after);
}

{
  "name": "edfringenow",
  "version": "1.60905.1",
  "private": true,
  "description": "EdFringeNow — client-side Edinburgh Fringe discovery + planner. No runtime dependencies; a build/serve-free static site.",
  "scripts": {
    "test": "node --test shared/__tests__/*.test.mjs js/__tests__/*.test.mjs plan/lib/__tests__/*.test.mjs plan2/lib/__tests__/*.test.mjs product/requirements/*.test.js product/requirements/logic/logic.test.js .claudinite/local/packs/*/*.test.mjs .claudinite/local/packs/edfringe-now/tasks/*.test.mjs .claudinite/local/packs/edfringe-now/tasks/*/*.test.mjs",
    "test:ui": "node --test --test-concurrency=1 product/requirements/screen/screen.test.js product/requirements/behavior/behavior.test.js",
    "refresh:ui": "node product/requirements/shared/refresh.js",
    "verify": "bash scripts/verify.sh",
    "setup-hooks": "bash scripts/setup-hooks.sh"
  }
}

import { basename } from 'node:path';
import { finding } from '../../../../engine/checks/helpers/findings.mjs';
import { COMMENT_CHECKABLE, commentOnly } from '../../../../engine/checks/helpers/code-scanning.mjs';

// The write-surface gate for the improve-comments pass. Its skill bounds every edit
// to comments in code files and to `README.md` documents; the pass runs unattended
// and writes the repo's OWN SOURCE — the one surface no other tidy-repo task
// touches — so the boundary needs a machine guarantee rather than a prose request.
//
// THE PERMISSION IS READ, NEVER ASSERTED. A file passes because its code is
// identical once the comments are stripped from both sides, not because the run
// says it only touched comments. That is the whole point: a run that quietly
// renamed a variable while "improving comments" is exactly what this catches, and
// a run cannot talk its way past a text comparison.
//
// THREE SHAPES FAIL, and each is deliberate rather than an oversight:
//   - a file whose language `commentOnly` cannot parse counts as code, so a comment
//     edit in one reds the run. Answering "I could not look" as a pass would make
//     the gate silently narrower than the languages a repo actually holds;
//   - an ADDED or DELETED code file is never comment-only, whatever it holds — a
//     whole file is a whole file, and this pass does not add or remove them;
//   - a DELETED `README.md` is not an improvement to a README. Modifying one is the
//     pass's business; deciding a document should not exist is not;
//   - ANY change under `.claudinite/`, comment-only or not. The mount is not the
//     repo's own source: `shared/` is vendored and the next converge replaces it
//     whole (that half is already invisible to every check — repo-context drops
//     the shared prefix), and `.claudinite/local/` is what the growth tasks write.
//     The task's precondition keeps the mount out of a round's scope; this is what
//     holds when a run reaches for one anyway.
//
// RELEVANCE IS THE PINNED COMMIT SUBJECT, the same self-gating shape
// claudinite-growth's capture gate uses: the run marks itself, so this rule can run
// everywhere tidy-repo is active — at the session Stop hook and on every PR — and
// costs ~nothing on a branch that is not this pass.
export const IMPROVE_COMMENTS_RUN = /^Claudinite tidy: improve comments/;

const isReadme = (p) => basename(p).toLowerCase() === 'readme.md';

// The same prefix the task's precondition filters its scope by (MOUNT_PREFIX in
// tasks/improve-comments/task.json); that task imports nothing, so the two are held
// in step by the test beside this check rather than by a shared constant.
const MOUNT_PREFIX = '.claudinite/';
const inMount = (p) => p.startsWith(MOUNT_PREFIX);

const rule = {
  id: 'improve-comments-scope',
  severity: 'blocking',
  scope: 'work',
  doc: 'packs/tidy-repo/skills/improve-comments/SKILL.md',
  description: 'An improve-comments run changes only comments in code files outside the .claudinite/ mount, and README.md documents',
  why: 'the pass runs unattended against the repo\'s own source, and its whole safety case is that a comment cannot change behaviour — a run that also moved a line has made an unreviewed code change wearing a housekeeping title',

  run(work) {
    if (work.onDefaultBranch()) return [];
    if (!work.commits.some((m) => IMPROVE_COMMENTS_RUN.test(m))) return [];

    const deleted = new Set(work.deleted);
    return [...new Set([...work.changedFiles, ...work.deleted])]
      .filter((p) => inMount(p) || (isReadme(p) ? deleted.has(p) : !commentOnly(p, work.readBase(p), work.read(p))))
      .sort()
      .map((p) => finding(rule, inMount(p)
        ? {
          file: p,
          what: `an improve-comments run changed ${p}, which is inside the ${MOUNT_PREFIX} mount`,
          fix: `revert ${p} — the mount is not this repo's source: the next converge replaces it whole, so a comment improved there is gone by morning; take the change to the canon instead`,
        }
        : isReadme(p)
        ? {
          file: p,
          what: `an improve-comments run deleted ${p} — a README may be improved, never removed`,
          fix: 'restore the file; deciding a document should not exist is a change that gets reviewed, not a comment pass',
        }
        : unparseable(p)
          ? {
            file: p,
            what: `an improve-comments run changed ${p}, whose language the comment parser cannot read`,
            fix: `revert ${p} — outside the parser's set a file counts as code, so nothing here can show the change was only comments; leave them to a change that gets reviewed`,
          }
          : {
            file: p,
            what: work.readBase(p) === null || deleted.has(p)
              ? `an improve-comments run added or deleted ${p}, which is never a comment-only change`
              : `an improve-comments run changed more than the comments in ${p}`,
            fix: 'keep the branch to comment text in code files and to README.md content — a rename, a moved line or a reformat is its own change, with its own review',
          }));
  },
};

// Whether the file's language is one `commentOnly` can parse at all. Only used to
// pick the remedy: a run told "you changed more than comments" about a `.py` file
// it only commented would go looking for a code edit that isn't there.
function unparseable(p) {
  const dot = p.lastIndexOf('.');
  return !COMMENT_CHECKABLE.has(dot === -1 ? '' : p.slice(dot).toLowerCase());
}

export default [rule];

content.content:
1	// /plan2 — the postcard trip planner, page logic.
2	//
3	// A wizard whose every answer becomes a sticker on a postcard, then the
4	// postcard turned over: a calendar of vertical days with one ticket per plan
5	// item, each of which peels off to reveal what to correct. The drafting itself
6	// is ./lib/draft.js (pure, deterministic); this file is state, rendering and
7	// gestures only. State persists in localStorage so the trip survives a reload.
8	
9	import { cityOf, festivalsIn, festivalsOn, routesFrom, showsOf, perfsBetween, daysBetween, addDays, dayOfWeek, monthName, shortDate, toMin, fromMin, citiesInMonth, genresOf, venueOf } from "./lib/world.js";
10	import { draftTrip, gapsOf, pickStay, pickRoute, DAY_START } from "./lib/draft.js";
11	
12	const STORE_KEY = "edfringe.plan2.v1";
13	const STEPS = ["where", "when", "who", "matters", "travel", "sleep", "draft"];
14	const CARD_TITLES = { where: "Where to?", when: "When?", who: "Who's coming?", matters: "What matters?", travel: "Getting there?", sleep: "Where to sleep?" };
15	const HOUR_PX = 40;
16	
17	const MODE_PIC = { train: "il-train", plane: "il-plane", car: "il-car", coach: "il-coach" };
18	const MODE_WORD = { train: "Train", plane: "Fly", car: "Drive", coach: "Coach" };
19	const COST = [["thrifty", "Thrifty", "il-wallet"], ["between", "In between", "il-jar"], ["splash", "Splash out", "il-champagne"]];
20	const PACE = [["packed", "Packed", "il-sprint"], ["steady", "Steady", "il-stroll"], ["leisurely", "Leisurely", "il-deckchair"]];
21	const FOCUS = [["festival", "Festival only", "il-curtain"], ["mix", "A mix", "il-picnic"], ["city", "City too", "il-city"]];
22	const PARTY = [["solo", "Just me", "il-solo"], ["couple", "A couple", "il-couple"], ["family", "Family", "il-family"], ["group", "Friends", "il-group"]];
23	const SLEEP = [["cost", "Cost", "il-wallet"], ["comfort", "Comfort", "il-hotel"], ["location", "Location", "ic-pin"]];
24	const AGES = [3, 5, 7, 9, 12, 15];
25	
26	const stage = document.getElementById("stage");
27	let world = null;
28	let state = null;
29	let ui = { way: "city", month: null, peel: null, chooser: false, more: 0, nameQuery: "" };
30	
31	// ------------------------------------------------------------------ state --
32	
33	function fresh() {
34	  return { v: 1, step: "where", answers: { cityId: null, festivalIds: [], from: null, to: null, party: null, cost: null, pace: null, focus: null, originId: null, mode: null, sleep: [] }, rules: {}, starred: [] };
35	}
36	
37	function load() {
38	  try {
39	    const raw = localStorage.getItem(STORE_KEY);
40	    if (raw) {
41	      const s = JSON.parse(raw);
42	      if (s && s.v === 1) return { ...fresh(), ...s, answers: { ...fresh().answers, ...s.answers } };
43	    }
44	  } catch (_) { /* a blocked or corrupt store just means a fresh postcard */ }
45	  return fresh();
46	}
47	
48	function save() {
49	  try { localStorage.setItem(STORE_KEY, JSON.stringify(state)); } catch (_) { /* fine */ }
50	}
51	
52	function set(fn) {
53	  fn(state);
54	  save();
55	  render();
56	}
57	
58	// ------------------------------------------------------------- utilities --
59	
60	const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
61	const use = (id, cls = "") => `<svg class="${cls}"><use href="#${id}"></use></svg>`;
62	const money = (city, n) => `${city.currency}${Number.isInteger(n) ? n : n.toFixed(2)}`;
63	const RING = `<svg class="ring" viewBox="0 0 140 110" preserveAspectRatio="none"><path d="M18 60C6 22 60 6 100 12c30 5 40 30 30 60-10 32-70 40-104 20C10 84 10 66 30 52"></path></svg>`;
64	
65	function answered(step) {
66	  const a = state.answers;
67	  switch (step) {
68	    case "where": return Boolean(a.cityId && a.festivalIds.length);
69	    case "when": return Boolean(a.from && a.to);
70	    case "who": return Boolean(a.party && (a.party.type !== "family" || (a.party.ages && a.party.ages.length)));
71	    case "matters": return Boolean(a.cost && a.pace && a.focus);
72	    case "travel": return Boolean(a.originId && a.mode);
73	    case "sleep": return a.sleep.length === 2;
74	    default: return true;
75	  }
76	}
77	
78	// The first question still without an answer, or null when the trip is
79	// fully described. The draft is only ever rendered in the null case: a
80	// question reopened and left half-answered comes back before the calendar.
81	function firstUnanswered() {
82	  return STEPS.find((step) => step !== "draft" && !answered(step)) || null;
83	}
84	
85	function primaryFestival() {
86	  return world.festivals.find((f) => f.id === state.answers.festivalIds[0]);
87	}
88	
89	function nights() {
90	  const a = state.answers;
91	  return a.from && a.to ? daysBetween(a.from, a.to).length - 1 : 0;
92	}
93	
94	function dateRange() {
95	  const a = state.answers;
96	  if (!a.from) return "";
97	  const [, m1, d1] = a.from.split("-").map(Number);
98	  const [, , d2] = a.to.split("-").map(Number);
99	  const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
100	  return `${d1}–${d2} ${months[m1 - 1]}`;
101	}
102	
103	// ------------------------------------------------------------ rendering --
104	
105	function render() {
106	  if (!world) return;
107	  const missing = firstUnanswered();
108	  if (state.step === "draft" && missing) { state.step = missing; save(); }
109	  stage.innerHTML = state.step === "draft" ? renderBack() : renderFront();
110	  wire();
111	}
112	
113	function stampHtml(f, cls = "", extra = "") {
114	  return `<div class="stamp ${cls}" style="--stamp:${f.colour}; ${extra}"><div class="art">${use(f.icon)}${esc(f.short)}<small>${esc(f.from.slice(8))}–${esc(f.to.slice(8))} ${monthName(f.from).slice(0, 3)}</small></div></div>`;
115	}
116	
117	function postmarkHtml(city, extra = "") {
118	  const a = state.answers;
119	  const big = a.from && a.to ? `${Number(a.from.slice(8))}–${Number(a.to.slice(8))}` : a.from ? `${Number(a.from.slice(8))}–` : "· · ·";
120	  const mid = a.from ? `${monthName(a.from).slice(0, 3).toUpperCase()} ${a.from.slice(0, 4)}` : "";
121	  const arrival = city && city.arrivals.train ? city.arrivals.train.name : city ? city.name : "";
122	  return `<svg class="postmark" viewBox="0 0 300 130" width="280" height="122" style="${extra}">
123	    <defs><path id="pmc" d="M64 26.5a38.5 38.5 0 1 1-.01 0"></path></defs>
124	    <circle class="ring" cx="64" cy="65" r="50"></circle><circle class="ring" cx="64" cy="65" r="34" stroke-width="1.5"></circle>
125	    <text><textPath href="#pmc">${esc((city ? city.name : "").toUpperCase())} · ${esc(arrival.toUpperCase())} ·</textPath></text>
126	    <text class="big" x="64" y="70" text-anchor="middle">${esc(big)}</text>
127	    <text class="mid" x="64" y="84" text-anchor="middle">${esc(mid)}</text>
128	    <g class="wave"><path d="M120 44q12-8 24 0t24 0 24 0 24 0 24 0 24 0 24 0"></path><path d="M120 58q12-8 24 0t24 0 24 0 24 0 24 0 24 0 24 0"></path><path d="M120 72q12-8 24 0t24 0 24 0 24 0 24 0 24 0 24 0"></path><path d="M120 86q12-8 24 0t24 0 24 0 24 0 24 0 24 0 24 0"></path></g>
129	  </svg>`;
130	}
131	
132	// Every answered question as a sticker, in the order asked. Clicking one
133	// reopens that question.
134	function answerStickers(exceptStep) {
135	  const a = state.answers;
136	  const city = a.cityId ? cityOf(world, a.cityId) : null;
137	  const out = [];
138	  const st = (step, cls, r, inner) => out.push(`<button type="button" class="sticker corner ${cls}" style="--r:${r}deg" data-reopen="${step}" title="Change this">${inner}</button>`);
139	  if (exceptStep !== "where" && city && answered("where")) {
140	    st("where", "label", -3, `${use("ic-pin")}${esc(city.name)}`);
141	  }
142	  if (exceptStep !== "when" && answered("when")) st("when", "label sun", 2, `${use("ic-sun")}${esc(dateRange())}`);
143	  if (exceptStep !== "who" && answered("who")) {
144	    const p = PARTY.find((x) => x[0] === a.party.type);
145	    const ages = a.party.type === "family" ? `<span class="sub">${a.party.ages.join(" · ")}</span>` : "";
146	    st("who", "wide", -2, `${use(p[2])}${p[1]}${ages}`);
147	  }
148	  if (exceptStep !== "matters" && answered("matters")) {
149	    st("matters", "sun", 4, `${use(COST.find((x) => x[0] === a.cost)[2])}${COST.find((x) => x[0] === a.cost)[1]}`);
150	    st("matters", "rose", -3, `${use(PACE.find((x) => x[0] === a.pace)[2])}${PACE.find((x) => x[0] === a.pace)[1]}`);
151	    st("matters", "mint", 2, `${use(FOCUS.find((x) => x[0] === a.focus)[2])}${FOCUS.find((x) => x[0] === a.focus)[1]}`);
152	  }
153	  if (exceptStep !== "travel" && answered("travel")) {
154	    const o = world.origins.find((x) => x.id === a.originId);
155	    st("travel", "wide", -2, `${use(MODE_PIC[a.mode])}${esc(o.station)}`);
156	  }
157	  if (exceptStep !== "sleep" && answered("sleep") && city) {
158	    const stay = pickStay(city, { ...a, notStay: state.rules.notStay });
159	    st("sleep", "rose", 3, `${use(stay.kind === "hotel" ? "il-hotel" : "il-guesthouse")}${esc(stay.name.replace(/^the\s+/i, "").split(/[\s,]/)[0])}`);
160	  }
161	  return out.join("");
162	}
163	
164	function renderFront() {
165	  const a = state.answers;
166	  const city = a.cityId ? cityOf(world, a.cityId) : null;
167	  const fests = city ? festivalsOn(world, city.id, a.from, a.to) : [];
168	  const on = fests.filter((f) => a.festivalIds.includes(f.id));
169	  const off = fests.filter((f) => !a.festivalIds.includes(f.id));
170	  const idx = STEPS.indexOf(state.step);
171	  const behind = STEPS.slice(idx + 1, idx + 3).filter((s) => s !== "draft");
172	
173	  return `
174	  <section class="front">
175	    <div class="postcard card-front">
176	      <div class="picture">${city ? use(city.picture) : `<div class="empty">Pick a city…</div>`}${city ? `<div class="big-name">${esc(city.name)}</div>` : ""}</div>
177	      <div class="stamps-on">${on.map((f, i) => stampHtml(f, "", `--r:${i % 2 ? 2.5 : -3}deg`)).join("")}</div>
178	      ${city ? postmarkHtml(city, "right: 120px; top: 4px; transform: rotate(-8deg);") : ""}
179	      <div class="answers on-card">${answerStickers(state.step)}</div>
180	      ${answered("where") ? "" : `<div class="caption">post card</div>`}
181	    </div>
182	    <div class="tape" style="left: -10px; top: 24px; transform: rotate(-42deg);"></div>
183	    <div class="tape teal" style="left: 660px; top: 0; transform: rotate(38deg);"></div>
184	    ${city && (state.step === "where" || state.step === "when") && off.length ? `
185	    <div class="stampsheet"><div class="title">Also on…</div>
186	      ${off.map((f, i) => `<button type="button" class="stamp peel" data-fest="${f.id}" style="--stamp:${f.colour}; --r:${i % 2 ? 3 : -2}deg" title="Add ${esc(f.name)} to the trip"><div class="art">${use(f.icon)}${esc(f.short)}<small>${esc(f.from.slice(8))}–${esc(f.to.slice(8))} ${monthName(f.from).slice(0, 3)}</small></div></button>`).join("")}
187	    </div><div class="tape gold" style="right: 90px; top: 30px; transform: rotate(4deg); width: 90px;"></div>` : ""}
188	    ${behind.map((s, i) => `<div class="qcard ${i ? "behind-2" : "behind"}"><div class="hole"></div><h2 style="opacity:.35">${CARD_TITLES[s]}</h2></div>`).join("")}
189	    <div class="qcard current"><div class="hole"></div>${renderCard(state.step)}</div>
190	    ${idx > 0 ? `<button type="button" class="tag-cta quiet back" data-nav="back">${use("ic-back")} Back</button>` : ""}
191	    <svg class="string" viewBox="0 0 200 120" width="160" height="96" style="right: 250px; top: 730px;"><path d="M10 10c30 40 60 60 100 70"></path></svg>
192	    <button type="button" class="tag-cta next" data-nav="next" ${answered(state.step) ? "" : "disabled"}>${state.step === "sleep" ? "Draft my trip" : "Next"} ${use("ic-arrow")}</button>
193	  </section>`;
194	}
195	
196	function optHtml(cls, key, pic, label, on, data) {
197	  return `<button type="button" class="opt ${cls} ${on ? "is-on" : ""}" ${data}="${key}">${use(pic)}<span>${label}</span>${RING}</button>`;
198	}
199	
200	function renderCard(step) {
201	  const a = state.answers;
202	  const city = a.cityId ? cityOf(world, a.cityId) : null;
203	  switch (step) {
204	    case "where": {
205	      const ways = [["city", "City", "ic-pin"], ["season", "Season", "ic-sun"], ["genre", "Genre", "ic-masks"], ["name", "Name", "ic-search"]];
206	      let chooser = "";
207	      if (ui.way === "city") {
208	        chooser = `<div class="chips">${world.cities.map((c) => `<button type="button" class="chip ${a.cityId === c.id ? "is-on" : ""}" data-city="${c.id}">${use("ic-pin")}${esc(c.name)}</button>`).join("")}</div>`;
209	      } else if (ui.way === "season") {
210	        const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
211	        chooser = `<div class="chips">${months.map((m, i) => { const cs = citiesInMonth(world, i + 1); return `<button type="button" class="chip ${cs.length ? "" : "ghost"} ${ui.month === i + 1 ? "is-on" : ""}" data-month="${i + 1}" ${cs.length ? "" : "disabled"}>${m}</button>`; }).join("")}</div>
212	          ${ui.month ? `<div class="chips" style="margin-top:10px">${citiesInMonth(world, ui.month).map((c) => `<button type="button" class="chip ${a.cityId === c.id ? "is-on" : ""}" data-city="${c.id}">${use("ic-pin")}${esc(c.name)}</button>`).join("")}</div>` : ""}`;
213	      } else if (ui.way === "genre") {
214	        const gs = genresOf(world);
215	        chooser = `<div class="chips">${gs.map((g) => `<button type="button" class="chip ${ui.genre === g ? "is-on" : ""}" data-genre="${esc(g)}">${esc(g)}</button>`).join("")}</div>
216	          ${ui.genre ? `<div class="chips" style="margin-top:10px">${world.festivals.filter((f) => f.genres.includes(ui.genre)).map((f) => `<button type="button" class="chip ${a.festivalIds[0] === f.id ? "is-on" : ""}" data-pick-fest="${f.id}">${use(f.icon)}${esc(f.short)} · ${esc(cityOf(world, f.cityId).name)}</button>`).join("")}</div>` : ""}`;
217	      } else {
218	        const q = ui.nameQuery.trim().toLowerCase();
219	        const hits = q ? world.festivals.filter((f) => f.name.toLowerCase().includes(q) || cityOf(world, f.cityId).name.toLowerCase().includes(q)) : [];
220	        chooser = `<input class="namebox" id="nameBox" type="search" placeholder="A festival you know…" value="${esc(ui.nameQuery)}" autocomplete="off">
221	          <div class="chips" style="margin-top:10px">${hits.map((f) => `<button type="button" class="chip ${a.festivalIds[0] === f.id ? "is-on" : ""}" data-pick-fest="${f.id}">${use(f.icon)}${esc(f.short)} · ${esc(cityOf(world, f.cityId).name)}</button>`).join("")}</div>`;
222	      }
223	      return `<h2>Where to?</h2>
224	        <div class="opts" style="margin-bottom:12px">${ways.map(([k, l, p]) => optHtml("sq" + (ui.way === k ? "" : " faded"), k, p, l, ui.way === k, "data-way")).join("")}</div>
225	        ${chooser}
226	        <div class="foot">${city ? `<span class="answer">${esc(city.name)} ${use("ic-tick")}</span>` : `<span class="note" style="color:var(--ink-faint)">…</span>`}</div>`;
227	    }
228	    case "when": {
229	      const f = primaryFestival();
230	      const base = ui.month || (f ? f.from.slice(0, 7) : "2026-08");
231	      const [y, m] = base.split("-").map(Number);
232	      const first = `${y}-${String(m).padStart(2, "0")}-01`;
233	      const daysInMonth = new Date(Date.UTC(y, m, 0)).getUTCDate();
234	      const startDow = (["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"].indexOf(dayOfWeek(first)));
235	      const cells = [];
236	      for (let i = 0; i < startDow; i++) cells.push(`<span class="out"></span>`);
237	      const fests = city ? festivalsIn(world, city.id) : [];
238	      for (let d = 1; d <= daysInMonth; d++) {
239	        const iso = `${y}-${String(m).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
240	        const inFest = fests.some((x) => x.from <= iso && x.to >= iso);
241	        const on = iso === a.from || iso === a.to;
242	        const within = a.from && a.to && iso > a.from && iso < a.to;
243	        cells.push(`<button type="button" class="${on ? "on" : ""} ${within ? "in" : ""} ${inFest ? "fest" : "out"}" data-day="${iso}">${d}</button>`);
244	      }
245	      const prev = `${m === 1 ? y - 1 : y}-${String(m === 1 ? 12 : m - 1).padStart(2, "0")}`;
246	      const next = `${m === 12 ? y + 1 : y}-${String(m === 12 ? 1 : m + 1).padStart(2, "0")}`;
247	      return `<h2>When?</h2>
248	        <div class="month"><button type="button" data-month-nav="${prev}" aria-label="Earlier month">‹</button><span>${monthName(first)} ${y}</span><button type="button" data-month-nav="${next}" aria-label="Later month">›</button></div>
249	        <div class="cal"><span class="h">M</span><span class="h">T</span><span class="h">W</span><span class="h">T</span><span class="h">F</span><span class="h">S</span><span class="h">S</span>${cells.join("")}</div>
250	        <div class="foot"><span class="note" style="color:var(--ink-faint);font-size:20px">${f ? esc(f.short) + " runs " + esc(f.from.slice(8)) + "–" + esc(f.to.slice(8)) : ""}</span><span class="note">${nights() ? nights() + " nights" : a.from ? "…and back?" : ""}</span></div>`;
251	    }
252	    case "who": {
253	      const p = a.party || {};
254	      return `<h2>Who's coming?</h2>
255	        <div class="opts">${PARTY.map(([k, l, pic]) => optHtml("", k, pic, l, p.type === k, "data-party")).join("")}</div>
256	        ${p.type === "family" ? `<div class="ages">Ages ${AGES.map((n) => `<button type="button" class="age ${(p.ages || []).includes(n) ? "is-on" : ""}" data-age="${n}">${n}</button>`).join("")}</div>` : ""}`;
257	    }
258	    case "matters": {
259	      const row = (lbl, list, key, attr) => `<div class="row-opts"><span class="lbl">${lbl}</span>${list.map(([k, l, pic]) => optHtml("", k, pic, l, a[key] === k, attr)).join("")}</div>`;
260	      return `<h2>What matters?</h2>${row("Cost", COST, "cost", "data-cost")}${row("Pace", PACE, "pace", "data-pace")}${row("Days", FOCUS, "focus", "data-focus")}`;
261	    }
262	    case "travel": {
263	      const origins = world.origins.filter((o) => routesFrom(world, o.id, a.cityId).length);
264	      const modes = a.originId ? routesFrom(world, a.originId, a.cityId) : [];
265	      return `<h2>Getting there?</h2>
266	        <div class="chips">${origins.map((o) => `<button type="button" class="chip ${a.originId === o.id ? "is-on" : ""}" data-origin="${o.id}">${esc(o.name)}</button>`).join("")}</div>
267	        ${modes.length ? `<div class="opts" style="margin-top:14px">${modes.map((r) => optHtml("sq", r.mode, MODE_PIC[r.mode], `${MODE_WORD[r.mode]} · ${Math.floor(r.minutes / 60)}h${String(r.minutes % 60).padStart(2, "0")}`, a.mode === r.mode, "data-mode")).join("")}</div>` : `<p class="note" style="color:var(--ink-faint);margin-top:14px">…from where?</p>`}`;
268	    }
269	    case "sleep": {
270	      const stay = city && a.sleep.length === 2 ? pickStay(city, a) : null;
271	      return `<h2>Where to sleep?</h2>
272	        <p class="note" style="color:var(--ink-faint);font-size:22px;margin:-8px 0 10px">pick two</p>
273	        <div class="opts">${SLEEP.map(([k, l, pic]) => optHtml("sq", k, pic, l, a.sleep.includes(k), "data-sleep")).join("")}</div>
274	        ${stay ? `<div class="foot"><span class="answer">${use(stay.kind === "hotel" ? "il-hotel" : "il-guesthouse")}${esc(stay.name)}</span><span class="note">${money(city, stay.perNight)} a night</span></div>` : ""}`;
275	    }
276	    default: return "";
277	  }
278	}
279	
280	// ---------------------------------------------------------- the back --
281	
282	function ticketClass(it) {
283	  return { show: "", meal: "food", out: "out", travel: "travel", stay: "stay", free: "free" }[it.kind] || "";
284	}
285	
286	function ticketHtml(it, city, key) {
287	  const top = ((it.start - DAY_START) / 60) * HOUR_PX;
288	  const h = Math.max(26, ((it.end - it.start) / 60) * HOUR_PX - 4);
289	  const size = h < 40 ? "tiny" : h < 58 ? "short" : "";
290	  if (it.kind === "free") return `<div class="tix free" style="top:${top}px;height:${h}px"><span class="n">free</span></div>`;
291	  const t = it.kind === "travel" ? `${fromMin(it.start)} → ${fromMin(it.end)}` : it.kind === "show" ? `${fromMin(it.start)} · ${money(city, it.unit)}` : it.kind === "meal" ? `${fromMin(it.start)}${it.booked ? " · booked" : ""}` : `${fromMin(it.start)} – ${fromMin(it.end)}`;
292	  const pic = it.kind === "show" ? it.icon : it.kind === "travel" ? MODE_PIC[it.mode] : it.picture;
293	  const band = it.kind === "show" ? `--band:${it.colour};` : "";
294	  const lifted = ui.peel === key ? "lift" : "";
295	  return `<button type="button" class="tix ${ticketClass(it)} ${size} ${it.starred ? "starred" : ""} ${lifted}" style="top:${top}px;height:${h}px;${band}" data-peel="${key}" data-kind="${it.kind}" ${it.oneOff ? 'data-oneoff="1"' : ""} title="${esc(it.title)}">
296	    <span class="t">${esc(t)}</span><span class="n">${esc(it.title)}</span><span class="v">${esc(it.sub || "")}</span>
297	    ${pic ? use(pic, "pic") : ""}${it.starred ? use("ic-star", "star") : ""}<i class="curl"></i></button>`;
298	}
299	
300	function revealHtml(it, city, top, side) {
301	  const S = (cls, pic, label, act, r) => `<button type="button" class="sticker ${cls}" style="--r:${r}deg" data-act="${act}">${use(pic)}${label}${act === "keep" || act === "leave" ? "" : use("ic-nope", "x")}</button>`;
302	  let inner = "";
303	  if (it.kind === "show" && it.oneOff) inner = S("rose", it.icon, "Not for me", "notShow", -3) + S("keep", "ic-star", "Keep it", "keep", 3);
304	  else if (it.kind === "show") {
305	    const venue = venueOf(city, it.venueId);
306	    inner = S("", "ic-clock", "Not this time", "notTime", -4) + S("", "ic-ticket", "Not this show", "notShow", 3) + S("lilac", world.genreIcons[it.genre] || "ic-masks", `No ${esc(it.genre.toLowerCase())}`, "notGenre", -2) + S("rose", "ic-pin", `Not ${esc(venue ? venue.short : "here")}`, "notVenue", 4) + S("keep", "ic-star", "Keep it", "keep", -3);
307	  } else if (it.kind === "meal") inner = S("", "il-table", "Somewhere else", "notMeal", -3) + S("rose", "ic-nope", "No meals", "noMeals", 2) + S("keep", "ic-star", "Keep it", "keep", 3);
308	  else if (it.kind === "out") inner = S("", "il-picnic", "Not this one", "notOut", -3) + S("rose", "ic-nope", "No day out", "noDayOut", 2) + S("keep", "ic-star", "Keep it", "keep", 3);
309	  else if (it.kind === "travel") inner = S("", "ic-clock", "Earlier", "earlier", -3) + S("", "ic-clock", "Later", "later", 2) + S("keep", "ic-star", "Keep it", "keep", 3);
310	  else if (it.kind === "stay") inner = S("", "il-hotel", "Another stay", "otherStay", -3) + S("keep", "ic-star", "Keep it", "keep", 3);
311	  return `<div class="reveal" style="top:${top}px;${side}">${inner}</div>`;
312	}
313	
314	function renderBack() {
315	  const a = state.answers;
316	  const city = cityOf(world, a.cityId);
317	  const trip = draftTrip(world, a, state.rules, state.starred);
318	  const days = trip.days;
319	  const hours = [];
320	  for (let h = 8; h <= 24; h++) hours.push(`<span style="top:${(h - 8) * HOUR_PX}px">${String(h).padStart(2, "0")}:00</span>`);
321	  const cols = days.map((d, di) => {
322	    const items = [...d.items];
323	    for (const g of gapsOf(d)) items.push({ kind: "free", start: g.start, end: Math.min(g.end, 24 * 60) });
324	    items.sort((x, y) => x.start - y.start);
325	    let peelHtml = "";
326	    const tickets = items.map((it) => {
327	      const key = `${di}:${it.kind}:${it.id || it.title}:${it.start}`;
328	      if (ui.peel === key) {
329	        const h = Math.max(26, ((it.end - it.start) / 60) * HOUR_PX - 4);
330	        const side = di >= days.length - 2 ? "right:-6px" : "left:-6px";
331	        peelHtml = revealHtml(it, city, ((it.start - DAY_START) / 60) * HOUR_PX + h + 8, side);
332	      }
333	      return ticketHtml(it, city, key);
334	    });
335	    return `<div class="daycol" data-day="${d.date}">${tickets.join("")}${peelHtml}</div>`;
336	  });
337	  const fest = primaryFestival();
338	  const stay = trip.stay;
339	  return `
340	  <div class="draft-head"><span class="title-hand">First draft</span><span class="pen-note">peel off what's wrong</span></div>
341	  <div class="draft-answers">${answerStickers("none")}</div>
342	  <div class="postcard back" style="--days:${days.length}">
343	    <div class="head">POST CARD</div>
344	    <div class="divider"></div>
345	    <div class="calwrap">
346	      <div class="calgrid">
347	        <div></div>${days.map((d) => `<div class="dayhead">${esc(shortDate(d.date).slice(0, 3))} ${Number(d.date.slice(8))}<small>${(n => n === 1 ? "1 show" : `${n} shows`)(d.items.filter((i) => i.kind === "show").length)}</small></div>`).join("")}
348	        <div class="hours">${hours.join("")}</div>${cols.join("")}
349	      </div>
350	    </div>
351	    <div class="stampbox"></div>
352	    ${fest ? stampHtml(fest, "", "right: 38px; top: 52px; --r: -2deg;") : ""}
353	    ${postmarkHtml(city, "right: 110px; top: 30px; transform: rotate(-6deg); width: 240px; height: 104px;")}
354	    <div class="addr"><span>${esc(stay.name)}</span><span>${esc(stay.address.split(",")[0])}</span><span>${esc(city.name)} ${esc(stay.address.split(",")[1] || "")}</span></div>
355	    <div class="totals"><span>${trip.totals.nights} nights <b>${money(city, trip.totals.stayCost)}</b></span><span>${MODE_WORD[trip.route ? trip.route.mode : "train"]} <b>${money(city, trip.totals.travel)}</b></span><span>Tickets <b>${money(city, trip.totals.tickets)}</b></span></div>
356	    <div class="nothing">Nothing booked yet</div>
357	    <div class="sheet"><div class="title">Stick on…</div>
358	      <button type="button" class="sticker mint" style="--r:-4deg" data-stick="out">${use("il-picnic")}Day out</button>
359	      <button type="button" class="sticker sun" style="--r:3deg" data-stick="meal">${use("il-table")}A meal</button>
360	      <button type="button" class="sticker lilac" style="--r:-2deg" data-stick="pick">${use("il-booklet")}Pick myself</button>
361	    </div>
362	  </div>
363	  <div class="draft-foot"><button type="button" class="tag-cta violet" style="--r:-2deg" data-nav="done">Looks good ${use("ic-tick")}</button></div>
364	  ${ui.chooser ? renderChooser(city, trip) : ""}`;
365	}
366	
367	function renderChooser(city, trip) {
368	  const a = state.answers;
369	  const inPlan = new Set(trip.days.flatMap((d) => d.items).filter((i) => i.kind === "show").map((i) => i.id));
370	  const days = daysBetween(a.from, a.to);
371	  const groups = a.festivalIds.map((fid) => {
372	    const f = world.festivals.find((x) => x.id === fid);
373	    const shows = showsOf(world, [fid]).filter((s) => perfsBetween(s, a.from, a.to).length);
374	    const starred = shows.filter((s) => state.starred.includes(s.id));
375	    const rest = shows.filter((s) => !state.starred.includes(s.id)).sort((x, y) => x.title.localeCompare(y.title));
376	    const limit = 5 + ui.more * 20;
377	    const rows = [...starred, ...rest.slice(0, limit)];
378	    const row = (s) => {
379	      const perfs = perfsBetween(s, a.from, a.to);
380	      const nightsOn = days.map((d) => perfs.some((p) => p.date === d));
381	      const venue = venueOf(city, s.venueId);
382	      return `<div class="crow ${state.starred.includes(s.id) ? "is-on" : ""}">
383	        <button type="button" class="starbtn" data-star="${s.id}" aria-label="Star ${esc(s.title)}">${use("ic-star")}</button>
384	        <div><div class="ttl">${esc(s.title)} ${inPlan.has(s.id) ? `<small class="meta">· in the plan</small>` : ""}</div><div class="meta">${esc(s.genre)} · ${esc(venue ? venue.name : "")} · ${s.minutes} min${s.ages ? ` · ${s.ages}+` : ""}${perfs.length === 1 ? " · one night only" : ""}</div></div>
385	        <div class="nights">${nightsOn.map((on) => `<i class="${on ? "on" : ""}"></i>`).join("")}</div>
386	        <div class="price">${s.price ? money(city, s.price) : "Free"}</div></div>`;
387	    };
388	    return `<h3><i style="--band:${f.colour}"></i>${esc(f.name)} <small>${shows.length} on your dates · ${starred.length} starred</small></h3>${rows.map(row).join("")}
389	      ${rest.length > limit ? `<div class="more"><button type="button" class="chip" data-more>Show 20 more of ${rest.length - limit}</button></div>` : ""}`;
390	  });
391	  return `<div class="chooser" id="chooser"><div class="book">
392	    <button type="button" class="tag-cta quiet close" style="--r:2deg" data-close-chooser>Back to the postcard ${use("ic-back")}</button>
393	    <h2>Pick myself</h2><p class="lede">Star what you want in. Starred shows stay in the plan and are never swapped.</p>
394	    ${groups.join("")}</div></div>`;
395	}
396	
397	// --------------------------------------------------------------- wiring --
398	
399	function next() {
400	  const i = STEPS.indexOf(state.step);
401	  set((s) => { s.step = STEPS[Math.min(STEPS.length - 1, i + 1)]; });
402	}
403	
404	function wire() {
405	  const on = (sel, fn) => stage.querySelectorAll(sel).forEach((el) => el.addEventListener("click", (e) => fn(el, e)));
406	  on("[data-nav]", (el) => {
407	    const nav = el.dataset.nav;
408	    if (nav === "next") next();
409	    else if (nav === "back") set((s) => { s.step = STEPS[Math.max(0, STEPS.indexOf(s.step) - 1)]; });
410	    else if (nav === "done") el.textContent = "Saved to this browser ✓";
411	  });
412	  on("[data-reopen]", (el) => { ui.peel = null; set((s) => { s.step = el.dataset.reopen; }); });
413	  on("[data-way]", (el) => { ui.way = el.dataset.way; render(); });
414	  on("[data-city]", (el) => pickCity(el.dataset.city));
415	  on("[data-month]", (el) => { ui.month = Number(el.dataset.month); render(); });
416	  on("[data-genre]", (el) => { ui.genre = el.dataset.genre; render(); });
417	  on("[data-pick-fest]", (el) => { const f = world.festivals.find((x) => x.id === el.dataset.pickFest); pickCity(f.cityId, f.id); });
418	  const nb = stage.querySelector("#nameBox");
419	  if (nb) { nb.addEventListener("input", () => { ui.nameQuery = nb.value; const pos = nb.selectionStart; render(); const again = stage.querySelector("#nameBox"); if (again) { again.focus(); again.setSelectionRange(pos, pos); } }); }
420	  on("[data-fest]", (el) => set((s) => { const id = el.dataset.fest; if (!s.answers.festivalIds.includes(id)) s.answers.festivalIds.push(id); }));
421	  on("[data-month-nav]", (el) => { ui.month = el.dataset.monthNav; render(); });
422	  on("[data-day]", (el) => set((s) => {
423	    const d = el.dataset.day;
424	    const a = s.answers;
425	    if (!a.from || (a.from && a.to)) { a.from = d; a.to = null; }
426	    else if (d < a.from) { a.to = a.from; a.from = d; }
427	    else if (d === a.from) { a.from = null; }
428	    else a.to = d;
429	    if (a.from && a.to) a.festivalIds = a.festivalIds.filter((id) => { const f = world.festivals.find((x) => x.id === id); return f.from <= a.to && f.to >= a.from; });
430	  }));
431	  on("[data-party]", (el) => set((s) => { const type = el.dataset.party; s.answers.party = { type, ages: type === "family" ? (s.answers.party && s.answers.party.ages) || [] : [] }; }));
432	  on("[data-age]", (el) => set((s) => { const n = Number(el.dataset.age); const ages = s.answers.party.ages; const i = ages.indexOf(n); if (i >= 0) ages.splice(i, 1); else ages.push(n); ages.sort((x, y) => x - y); }));
433	  on("[data-cost]", (el) => set((s) => { s.answers.cost = el.dataset.cost; }));
434	  on("[data-pace]", (el) => set((s) => { s.answers.pace = el.dataset.pace; }));
435	  on("[data-focus]", (el) => set((s) => { s.answers.focus = el.dataset.focus; }));
436	  on("[data-origin]", (el) => set((s) => { s.answers.originId = el.dataset.origin; const modes = routesFrom(world, s.answers.originId, s.answers.cityId); if (!modes.some((r) => r.mode === s.answers.mode)) s.answers.mode = null; }));
437	  on("[data-mode]", (el) => set((s) => { s.answers.mode = el.dataset.mode; }));
438	  on("[data-sleep]", (el) => set((s) => { const k = el.dataset.sleep; const sl = s.answers.sleep; const i = sl.indexOf(k); if (i >= 0) sl.splice(i, 1); else { sl.push(k); if (sl.length > 2) sl.shift(); } }));
439	  // the back
440	  on("[data-peel]", (el, e) => { e.stopPropagation(); ui.peel = ui.peel === el.dataset.peel ? null : el.dataset.peel; render(); });
441	  on("[data-act]", (el, e) => { e.stopPropagation(); correct(el.dataset.act); });
442	  on("[data-stick]", (el) => stick(el.dataset.stick));
443	  on("[data-close-chooser]", () => { ui.chooser = false; render(); });
444	  on("[data-more]", () => { ui.more += 1; render(); });
445	  on("[data-star]", (el) => set((s) => { const id = el.dataset.star; const i = s.starred.indexOf(id); if (i >= 0) s.starred.splice(i, 1); else s.starred.push(id); }));
446	  const chooser = stage.querySelector("#chooser");
447	  if (chooser) chooser.addEventListener("click", (e) => { if (e.target === chooser) { ui.chooser = false; render(); } });
448	}
449	
450	function pickCity(cityId, festivalId) {
451	  set((s) => {
452	    const a = s.answers;
453	    if (a.cityId !== cityId) { a.from = null; a.to = null; a.originId = null; a.mode = null; s.rules = {}; s.starred = []; }
454	    a.cityId = cityId;
455	    const fests = festivalsIn(world, cityId);
456	    a.festivalIds = festivalId ? [festivalId] : [fests[0].id];
457	    ui.month = null;
458	  });
459	}
460	
461	// A correction is a rule the drafter obeys from now on; the peeled ticket's
462	// own facts (which show, which genre, which venue, which night) are the rule.
463	function correct(act) {
464	  const key = ui.peel;
465	  if (!key) return;
466	  const [di, kind] = key.split(":");
467	  const a = state.answers;
468	  const trip = draftTrip(world, a, state.rules, state.starred);
469	  const day = trip.days[Number(di)];
470	  const it = day && day.items.find((x) => `${di}:${x.kind}:${x.id || x.title}:${x.start}` === key);
471	  if (!it && kind !== "free") { ui.peel = null; render(); return; }
472	  const push = (r, k, v) => { r[k] = r[k] || []; if (!r[k].includes(v)) r[k].push(v); };
473	  set((s) => {
474	    const r = s.rules;
475	    switch (act) {
476	      case "keep": if (it.kind === "show" && !s.starred.includes(it.id)) s.starred.push(it.id); break;
477	      case "notTime": push(r, "notTime", it.perf); break;
478	      case "notShow": push(r, "notShow", it.id); s.starred = s.starred.filter((x) => x !== it.id); break;
479	      case "notGenre": push(r, "notGenre", it.genre); break;
480	      case "notVenue": push(r, "notVenue", it.venueId); break;
481	      case "notMeal": push(r, "notMeal", it.id); break;
482	      case "noMeals": r.noMeals = true; break;
483	      case "notOut": push(r, "notOut", it.id); break;
484	      case "noDayOut": r.noDayOut = true; r.stickOut = []; break;
485	      case "earlier": r.travelShift = (r.travelShift || 0) - 1; break;
486	      case "later": r.travelShift = (r.travelShift || 0) + 1; break;
487	      case "otherStay": {
488	        const city = cityOf(world, a.cityId);
489	        const cur = pickStay(city, a);
490	        push(r, "notStay", cur.id);
491	        break;
492	      }
493	      default: break;
494	    }
495	  });
496	  ui.peel = null;
497	  render();
498	}
499	
500	function stick(what) {
501	  if (what === "pick") { ui.chooser = true; ui.more = 0; render(); return; }
502	  const a = state.answers;
503	  const days = daysBetween(a.from, a.to);
504	  set((s) => {
505	    const r = s.rules;
506	    if (what === "out") {
507	      r.noDayOut = false;
508	      const trip = draftTrip(world, a, r, s.starred);
509	      const free = trip.days.slice(1, -1).find((d) => !d.items.some((i) => i.kind === "out"));
510	      if (free) { r.stickOut = r.stickOut || []; r.stickOut.push(free.date); }
511	    } else if (what === "meal") {
512	      r.noMeals = false;
513	      r.notMeal = [];
514	      const trip = draftTrip(world, a, r, s.starred);
515	      const lacking = trip.days.find((d) => !d.items.some((i) => i.kind === "meal" && i.start >= 17 * 60));
516	      if (lacking) { r.stickMeal = r.stickMeal || []; if (!r.stickMeal.includes(lacking.date)) r.stickMeal.push(lacking.date); }
517	    }
518	  });
519	  void days;
520	}
521	
522	// ----------------------------------------------------------------- boot --
523	
524	async function boot() {
525	  if (new URLSearchParams(location.search).has("reset")) { try { localStorage.removeItem(STORE_KEY); } catch (_) { /* fine */ } history.replaceState(null, "", location.pathname); }
526	  const [symbols, data] = await Promise.all([fetch("symbols.svg").then((r) => r.text()), fetch("data/world.json").then((r) => r.json())]);
527	  document.getElementById("symbols").innerHTML = symbols;
528	  world = data;
529	  state = load();
530	  document.getElementById("resetBtn").addEventListener("click", () => { state = fresh(); ui = { way: "city", month: null, peel: null, chooser: false, more: 0, nameQuery: "" }; save(); render(); });
531	  render();
532	  document.body.dataset.ready = "1";
533	}
534	
535	boot();
536

