1	// The drafter: answers + corrections + the world → one deterministic trip.
2	// No randomness, no clock: the same inputs always draft the same plan, so a
3	// golden can pin it and a correction re-drafts predictably.
4	//
5	// answers: { cityId, festivalIds, from, to, party: {type, ages}, cost, pace,
6	//            focus, originId, mode, sleep: [two of cost|comfort|location] }
7	// rules:   { notShow: [id], notGenre: [genre], notVenue: [venueId],
8	//            notTime: ["showId@date"], notMeal: [id], notOut: [id],
9	//            noDayOut: bool, noMeals: bool, travelShift: -1|0|1 }
10	// starred: [showId]   — must be in the plan, never swapped
11	// picks:   [showId]   — chosen by hand in the content chooser (same as starred)
12	
13	import { perfsBetween, toMin, fromMin, daysBetween, dayOfWeek, walkMinutes, cityOf, venueOf, showsOf, routesFrom } from "./world.js";
14	
15	const DAY_START = 8 * 60; // the calendar's first hour
16	const DAY_END = 24 * 60;
17	const GAP = 15; // minutes between the end of one thing and the start of the next
18	
19	const PACE_SHOWS = { packed: 5, steady: 3, leisurely: 2 };
20	const COST_CAP = { thrifty: 14, between: 24, splash: Infinity };
21	const COST_TABLE = { thrifty: 1, between: 2, splash: 3 }; // restaurant price band ceiling
22	
23	function youngest(party) {
24	  if (!party || party.type !== "family" || !party.ages || !party.ages.length) return null;
25	  return Math.min(...party.ages);
26	}
27	
28	function partySize(party) {
29	  if (!party) return 2;
30	  if (party.type === "solo") return 1;
31	  if (party.type === "couple") return 2;
32	  if (party.type === "family") return 2 + (party.ages ? party.ages.length : 1);
33	  return 5;
34	}
35	
36	// The evening ends earlier with small children: last show must START by then.
37	function lastStart(party) {
38	  const y = youngest(party);
39	  if (y !== null && y < 8) return 19 * 60 + 30;
40	  if (y !== null) return 20 * 60 + 30;
41	  return 22 * 60 + 30;
42	}
43	
44	export function pickStay(city, answers) {
45	  const wants = new Set(answers.sleep || ["cost", "location"]);
46	  const size = partySize(answers.party);
47	  const scored = city.hotels
48	    .filter((h) => h.sleeps >= size)
49	    .filter((h) => !(answers.notStay || []).includes(h.id))
50	    .map((h) => ({ h, score: ["cost", "comfort", "location"].reduce((s, k) => s + (wants.has(k) ? h[k] * 2 : h[k]), 0) }))
51	    .sort((a, b) => b.score - a.score || a.h.perNight - b.h.perNight || a.h.id.localeCompare(b.h.id));
52	  return scored.length ? scored[0].h : city.hotels[0];
53	}
54	
55	export function pickRoute(world, answers) {
56	  const routes = routesFrom(world, answers.originId, answers.cityId);
57	  if (!routes.length) return null;
58	  return routes.find((r) => r.mode === answers.mode) || routes[0];
59	}
60	
61	function travelLegs(world, city, answers, rules, stay) {
62	  const route = pickRoute(world, answers);
63	  if (!route) return { out: null, back: null, route: null };
64	  const shift = rules.travelShift || 0;
65	  const arrival = city.arrivals[route.mode] || city.arrivals.train;
66	  const transfer = arrival && arrival.transferMin ? arrival.transferMin : 0;
67	  // Outbound: the departure that lands around lunchtime, nudged by the shift.
68	  const deps = route.departures.map(toMin);
69	  let outIdx = deps.findIndex((d) => d + route.minutes >= 12 * 60);
70	  if (outIdx < 0) outIdx = deps.length - 1;
71	  outIdx = Math.max(0, Math.min(deps.length - 1, outIdx + shift));
72	  const outDep = deps[outIdx];
73	  const out = { kind: "travel", mode: route.mode, start: outDep, end: outDep + route.minutes, title: `${world.origins.find((o) => o.id === answers.originId).station} → ${arrival.name}`, sub: `${route.operator} · ${partySize(answers.party)} seats`, price: route.price * partySize(answers.party), at: [arrival.lat, arrival.lng], transferMin: transfer };
74	  // Homeward: leave mid-afternoon on the last day so the morning is free.
75	  let backIdx = deps.findIndex((d) => d >= 15 * 60);
76	  if (backIdx < 0) backIdx = deps.length - 1;
77	  backIdx = Math.max(0, Math.min(deps.length - 1, backIdx + shift));
78	  const backDep = deps[backIdx];
79	  const back = { kind: "travel", mode: route.mode, start: backDep, end: backDep + route.minutes, title: `${arrival.name} → ${world.origins.find((o) => o.id === answers.originId).station}`, sub: `${route.operator} · ${partySize(answers.party)} seats`, price: route.price * partySize(answers.party), at: [stay.lat, stay.lng], transferMin: transfer };
80	  return { out, back, route };
81	}
82	
83	function isOneOff(show, from, to) {
84	  return perfsBetween(show, from, to).length === 1;
85	}
86	
87	function mealFor(city, answers, rules, which, when, near, usedIds, latestStart = when.min + 90) {
88	  if (rules.noMeals) return null;
89	  const y = youngest(answers.party);
90	  const cap = COST_TABLE[answers.cost] || 2;
91	  const day = dayOfWeek(when.date);
92	  const cands = city.restaurants
93	    .filter((r) => r.meals.includes(which))
94	    .filter((r) => !(rules.notMeal || []).includes(r.id))
95	    .filter((r) => y === null || r.kids)
96	    .filter((r) => r.price <= cap)
97	    .filter((r) => !r.days || r.days.includes(day))
98	    .filter((r) => !usedIds.has(r.id))
99	    .map((r) => {
100	      const slot = r.slots.map(toMin).find((s) => s >= when.min) ?? null;
101	      return { r, slot, walk: walkMinutes(near, [r.lat, r.lng]) };
102	    })
103	    .filter((x) => x.slot !== null && x.slot <= latestStart)
104	    .sort((a, b) => a.walk - b.walk || a.r.price - b.r.price || a.r.id.localeCompare(b.r.id));
105	  if (!cands.length) return null;
106	  const { r, slot } = cands[0];
107	  usedIds.add(r.id);
108	  const booked = r.bookable;
109	  return { kind: "meal", id: r.id, start: slot, end: slot + (which === "lunch" ? 60 : 75), title: r.name, sub: booked ? `table for ${partySize(answers.party)} · ${r.cuisine}` : `walk in · ${r.cuisine}`, booked, price: 0, at: [r.lat, r.lng], picture: "il-table" };
110	}
111	
112	function dayOutFor(city, answers, rules, date, used) {
113	  if (rules.noDayOut) return null;
114	  const y = youngest(answers.party);
115	  const cands = city.excursions
116	    .filter((e) => !(rules.notOut || []).includes(e.id))
117	    .filter((e) => !used.has(e.id))
118	    .filter((e) => y === null || y >= e.kidsMin)
119	    .filter((e) => (COST_CAP[answers.cost] || Infinity) >= e.price)
120	    .sort((a, b) => a.id.localeCompare(b.id));
121	  if (!cands.length) return null;
122	  const e = cands[0];
123	  used.add(e.id);
124	  const start = toMin(e.start);
125	  return { kind: "out", id: e.id, start, end: start + e.hours * 60, title: e.name, sub: e.sub, price: e.price * partySize(answers.party), at: [city.lat, city.lng], picture: e.picture };
126	}
127	
128	// Which full days get a day out: focus decides the count, the middle of the
129	// trip gets the first one, then every other day outward.
130	function dayOutDates(days, focus, stuckOn) {
131	  const full = days.slice(1, -1);
132	  const want = focus === "festival" ? 0 : focus === "city" ? Math.ceil(full.length / 2) : full.length ? 1 : 0;
133	  const order = [];
134	  const mid = Math.floor(full.length / 2);
135	  for (let i = 0; i < full.length; i++) {
136	    const idx = i % 2 === 0 ? mid + Math.ceil(i / 2) : mid - Math.ceil(i / 2);
137	    if (idx >= 0 && idx < full.length && !order.includes(full[idx])) order.push(full[idx]);
138	  }
139	  const chosen = new Set(order.slice(0, want));
140	  for (const d of stuckOn || []) chosen.add(d);
141	  return chosen;
142	}
143	
144	export function draftTrip(world, answers, rules = {}, starred = []) {
145	  const city = cityOf(world, answers.cityId);
146	  const days = daysBetween(answers.from, answers.to);
147	  const stay = pickStay(city, { ...answers, notStay: rules.notStay });
148	  const { out, back, route } = travelLegs(world, city, answers, rules, stay);
149	  const shows = showsOf(world, answers.festivalIds || []);
150	  const y = youngest(answers.party);
151	  const cap = COST_CAP[answers.cost] || Infinity;
152	  const perDay = PACE_SHOWS[answers.pace] || 3;
153	  const latest = lastStart(answers.party);
154	  const starSet = new Set(starred);
155	  const notShow = new Set(rules.notShow || []);
156	  const notGenre = new Set(rules.notGenre || []);
157	  const notVenue = new Set(rules.notVenue || []);
158	  const notTime = new Set(rules.notTime || []);
159	  const usedShows = new Set();
160	  const usedMeals = new Set();
161	  const usedOuts = new Set();
162	  const outDates = dayOutDates(days, answers.focus, rules.stickOut);
163	
164	  const eligible = (s) =>
165	    !notShow.has(s.id) && !notGenre.has(s.genre) && !notVenue.has(s.venueId) && (starSet.has(s.id) || ((y === null || s.ages <= y) && s.price <= cap && (y === null || s.ages < 16)));
166	
167	  const result = { days: [], stay, route, totals: { nights: days.length - 1, stayCost: stay.perNight * (days.length - 1), travel: (out ? out.price : 0) + (back ? back.price : 0), tickets: 0 } };
168	
169	  for (let di = 0; di < days.length; di++) {
170	    const date = days[di];
171	    const first = di === 0;
172	    const last = di === days.length - 1;
173	    const items = [];
174	    let cursor = DAY_START + 60; // 09:00 unless travel says otherwise
175	    let near = [stay.lat, stay.lng];
176	    let dayEnd = DAY_END;
177	
178	    if (first && out) {
179	      items.push({ ...out, date });
180	      cursor = out.end + out.transferMin + GAP;
181	      near = out.at;
182	      const checkIn = Math.max(cursor, 14 * 60);
183	      items.push({ kind: "stay", date, start: checkIn, end: checkIn + 30, title: "Check in", sub: stay.name, price: 0, at: [stay.lat, stay.lng], picture: stay.kind === "hotel" ? "il-hotel" : "il-guesthouse" });
184	      cursor = checkIn + 30 + GAP;
185	      near = [stay.lat, stay.lng];
186	    }
187	    if (last && back) {
188	      items.push({ kind: "stay", date, start: 10 * 60, end: 10 * 60 + 30, title: "Check out", sub: "bags stay at the desk", price: 0, at: [stay.lat, stay.lng], picture: stay.kind === "hotel" ? "il-hotel" : "il-guesthouse" });
189	      cursor = Math.max(cursor, 10 * 60 + 30 + GAP);
190	      dayEnd = back.start - back.transferMin - 45;
191	      items.push({ ...back, date });
192	    }
193	
194	    if (outDates.has(date) && !first && !last) {
195	      const o = dayOutFor(city, answers, rules, date, usedOuts);
196	      if (o) items.push({ ...o, date, at: [stay.lat, stay.lng] });
197	    }
198	
199	    // Shows: fit around what the day already holds (travel, the stay, a day
200	    // out), starred and hand-picked shows first, then the best fit for each
201	    // remaining hole — a late starred concert never blocks the afternoon.
202	    const genresToday = new Set();
203	    const budget = perDay + starSet.size;
204	    let count = 0;
205	    const fits = (venueAt, start, end) => {
206	      const sorted = [...items].sort((a, b) => a.start - b.start);
207	      for (const it of sorted) {
208	        if (it.end + GAP + walkMinutes(it.at, venueAt) > start && it.start - GAP - walkMinutes(venueAt, it.at) < end) return null;
209	      }
210	      const prev = sorted.filter((it) => it.end <= start).at(-1);
211	      return { prev, gapBefore: prev ? start - prev.end : start - (DAY_START + 60) };
212	    };
213	    while (count < budget) {
214	      const cands = [];
215	      for (const s of shows) {
216	        if (usedShows.has(s.id) || !eligible(s)) continue;
217	        const venue = venueOf(city, s.venueId);
218	        const at = venue ? [venue.lat, venue.lng] : [stay.lat, stay.lng];
219	        for (const p of perfsBetween(s, answers.from, answers.to)) {
220	          if (p.date !== date || notTime.has(`${s.id}@${p.date}`)) continue;
221	          const start = toMin(p.time);
222	          const end = start + s.minutes;
223	          if (start < DAY_START + 60 || start > latest || end > dayEnd) continue;
224	          const fit = fits(at, start, end);
225	          if (!fit) continue;
226	          let score = 0;
227	          if (starSet.has(s.id)) score += 1000;
228	          score -= fit.gapBefore / 10; // fill the day from the front, don't leave holes
229	          score -= fit.prev ? walkMinutes(fit.prev.at, at) : 0;
230	          if (genresToday.has(s.genre)) score -= 25;
231	          if (answers.cost === "thrifty") score -= s.price;
232	          if (y !== null && s.ages <= y && s.ages > 0) score += 10; // made for the kids
233	          cands.push({ s, p, start, end, at, score });
234	        }
235	      }
236	      if (!cands.length) break;
237	      cands.sort((a, b) => b.score - a.score || a.start - b.start || a.s.id.localeCompare(b.s.id));
238	      const { s, p, start, end, at } = cands[0];
239	      const venue = venueOf(city, s.venueId);
240	      const festival = world.festivals.find((f) => f.id === s.festivalId);
241	      items.push({ kind: "show", id: s.id, perf: `${s.id}@${p.date}`, date, start, end, title: s.title, sub: venue ? venue.name : "", venueId: s.venueId, genre: s.genre, festivalId: s.festivalId, colour: festival.colour, icon: festival.icon, price: s.price * partySize(answers.party), unit: s.price, oneOff: isOneOff(s, answers.from, answers.to), starred: starSet.has(s.id), at });
242	      usedShows.add(s.id);
243	      genresToday.add(s.genre);
244	      count++;
245	      result.totals.tickets += s.price * partySize(answers.party);
246	    }
247	    // Meals into the gaps: lunch in the midday window, dinner in the evening
248	    // one; a stuck-on meal insists on a dinner even on the last day.
249	    items.sort((a, b) => a.start - b.start);
250	    const stuckMeal = (rules.stickMeal || []).includes(date);
251	    const windows = [["lunch", 11 * 60 + 30, 14 * 60 + 45, 60], ["dinner", 17 * 60 + 30, (last && !stuckMeal) ? dayEnd : 21 * 60 + 30, 75]];
252	    for (const [which, wFrom, wTo, dur] of windows) {
253	      if (which === "dinner" && last && !stuckMeal && dayEnd < 19 * 60) continue;
254	      const gaps = [];
255	      let c = first && out ? out.end + out.transferMin : DAY_START + 60;
256	      for (const it of items) { if (it.start - c >= dur + GAP) gaps.push([c, it.start - GAP, it]); c = Math.max(c, it.end + GAP); }
257	      if (Math.min(dayEnd, DAY_END) - c >= dur + GAP) gaps.push([c, Math.min(dayEnd, DAY_END) - GAP, null]);
258	      for (const [gFrom, gTo] of gaps) {
259	        const from = Math.max(gFrom, wFrom);
260	        const to = Math.min(gTo, wTo);
261	        if (to - from < dur) continue;
262	        const before = [...items].reverse().find((it) => it.end <= from + GAP);
263	        const m = mealFor(city, answers, rules, which, { date, min: from }, before ? before.at : [stay.lat, stay.lng], usedMeals, to - dur);
264	        if (m) { m.end = m.start + dur; items.push({ ...m, date }); break; }
265	      }
266	    }
267	    items.sort((a, b) => a.start - b.start);
268	    result.days.push({ date, items });
269	  }
270	  result.totals.tickets += result.days.flatMap((d) => d.items).filter((i) => i.kind === "out").reduce((s, i) => s + i.price, 0);
271	  return result;
272	}
