274	// Free gaps of an hour or more between a day's items, for the dashed "free"
275	// tickets and for stick-on placement.
276	export function gapsOf(day, from = DAY_START + 60, to = 23 * 60) {
277	  const gaps = [];
278	  let cursor = from;
279	  for (const it of day.items) {
280	    if (it.start - cursor >= 60) gaps.push({ start: cursor, end: it.start });
281	    cursor = Math.max(cursor, it.end + GAP);
282	  }
283	  if (to - cursor >= 60) gaps.push({ start: cursor, end: to });
