1	// The test-data world for /plan2: performance expansion, lookups and the few
2	// geographic helpers the drafter needs. Pure functions over the committed
3	// plan2/data/world.json shape; nothing here touches the DOM or the network.
4	
5	const DOW = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
6	
7	export function toMin(hhmm) {
8	  const [h, m] = hhmm.split(":").map(Number);
9	  return h * 60 + m;
10	}
11	
12	export function fromMin(min) {
13	  const h = Math.floor(min / 60);
14	  const m = min % 60;
15	  return `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}`;
16	}
17	
18	// ISO date arithmetic without time zones: dates are calendar days, full stop.
19	export function addDays(iso, n) {
20	  const [y, m, d] = iso.split("-").map(Number);
21	  const t = Date.UTC(y, m - 1, d + n);
22	  return new Date(t).toISOString().slice(0, 10);
23	}
24	
25	export function dayOfWeek(iso) {
26	  const [y, m, d] = iso.split("-").map(Number);
27	  return DOW[new Date(Date.UTC(y, m - 1, d)).getUTCDay()];
28	}
29	
30	export function daysBetween(from, to) {
31	  const out = [];
32	  for (let d = from; d <= to; d = addDays(d, 1)) out.push(d);
33	  return out;
34	}
35	
36	export function shortDate(iso) {
37	  const [, m, d] = iso.split("-").map(Number);
38	  const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
39	  return `${dayOfWeek(iso)} ${d} ${months[m - 1]}`;
40	}
41	
42	export function monthName(iso) {
43	  const months = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
44	  return months[Number(iso.split("-")[1]) - 1];
45	}
46	
47	// A show's performances as [{date, time}] — the JSON carries a rule, not the
48	// list, so a run of a month reads as one line. Late-night starts (01:00) are
49	// kept on the calendar day they fall on; the drafter treats them as the
50	// previous evening's tail.
51	export function expandPerfs(show) {
52	  const p = show.perfs;
53	  if (p.dates) return p.dates.map(([date, time]) => ({ date, time }));
54	  const out = [];
55	  if (p.daily) {
56	    const except = new Set(p.daily.except || []);
57	    const skip = new Set(p.daily.skipDays || []);
58	    for (const date of daysBetween(p.daily.from, p.daily.to)) {
59	      if (except.has(date) || skip.has(dayOfWeek(date))) continue;
60	      out.push({ date, time: p.daily.time });
61	    }
62	  }
63	  if (p.weekly) {
