1	    .browse { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; margin: 22px 0 18px; }
2	    .browse-tile { display: flex; align-items: center; gap: 12px; padding: 16px 18px; border-radius: 14px; border: 1px solid var(--line); background: #fff; font-weight: 700; }
3	    .browse-tile.is-active { border-color: var(--violet); background: rgba(108,76,241,0.05); color: var(--violet-dark); box-shadow: 0 0 0 3px rgba(108,76,241,0.12); }
4	    .browse-tile svg { width: 22px; height: 22px; }
5	    .browse-tile small { display: block; font-weight: 400; color: var(--muted); font-size: 0.78rem; }
6	    .search { display: flex; align-items: center; gap: 10px; padding: 12px 16px; border: 1px solid var(--line); border-radius: 12px; background: #fff; color: var(--muted); margin-bottom: 18px; }
7	    .fest-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 18px; }
8	    .fest { display: flex; flex-direction: column; border-radius: var(--radius); background: #fff; border: 1px solid var(--line); overflow: hidden; }
9	    .fest.is-selected { border-color: var(--violet); box-shadow: 0 0 0 3px rgba(108,76,241,0.18), var(--shadow-soft); }
10	    .poster { position: relative; height: 150px; padding: 18px 20px; display: flex; flex-direction: column; justify-content: flex-end; color: #fff; }
11	    .poster .month { position: absolute; top: 16px; left: 20px; font-size: 0.72rem; font-weight: 800; letter-spacing: 0.12em; text-transform: uppercase; opacity: 0.85; }
12	    .poster .name { font-family: var(--display); font-weight: 800; font-size: 1.7rem; line-height: 1.05; letter-spacing: -0.02em; }
13	    .poster .check { position: absolute; top: 14px; right: 14px; width: 28px; height: 28px; border-radius: 999px; background: #fff; color: var(--violet); display: grid; place-items: center; }
14	    .fest-body { padding: 14px 18px 16px; display: flex; flex-direction: column; gap: 10px; }
15	    .fest-meta { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; font-size: 0.86rem; color: var(--muted); }
16	    .fest-meta b { color: var(--ink); }
17	    .fest-tags { display: flex; flex-wrap: wrap; gap: 6px; }
18	    .fest-foot { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-top: 4px; }
19	    .also { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; padding: 12px 14px; border-radius: 12px; background: var(--eif-bg); font-size: 0.86rem; }
20	    .dates { display: grid; grid-template-columns: 1fr auto; gap: 20px; align-items: center; margin-top: 24px; padding: 18px 22px; }
21	    .date-row { display: flex; align-items: center; gap: 10px; }
22	    .date-box { display: flex; flex-direction: column; padding: 10px 14px; border: 1px solid var(--line); border-radius: 12px; min-width: 150px; background: #fff; }
23	    .date-box span { font-size: 0.7rem; font-weight: 800; text-transform: uppercase; letter-spacing: 0.05em; color: var(--muted); }
24	    .date-box b { font-size: 1.05rem; }
25	    .strip { display: flex; gap: 3px; }
26	    .strip i { display: block; width: 14px; height: 22px; border-radius: 3px; background: #eef0f5; }
27	    .strip i.on { background: var(--violet); }
28	    .strip i.eif { background: var(--eif); }
