file.content:
.browse { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; margin: 22px 0 18px; }
.browse-tile { display: flex; align-items: center; gap: 12px; padding: 16px 18px; border-radius: 14px; border: 1px solid var(--line); background: #fff; font-weight: 700; }
.browse-tile.is-active { border-color: var(--violet); background: rgba(108,76,241,0.05); color: var(--violet-dark); box-shadow: 0 0 0 3px rgba(108,76,241,0.12); }
.browse-tile svg { width: 22px; height: 22px; }
.browse-tile small { display: block; font-weight: 400; color: var(--muted); font-size: 0.78rem; }
.search { display: flex; align-items: center; gap: 10px; padding: 12px 16px; border: 1px solid var(--line); border-radius: 12px; background: #fff; color: var(--muted); margin-bottom: 18px; }
.fest-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 18px; }
.fest { display: flex; flex-direction: column; border-radius: var(--radius); background: #fff; border: 1px solid var(--line); overflow: hidden; }
.fest.is-selected { border-color: var(--violet); box-shadow: 0 0 0 3px rgba(108,76,241,0.18), var(--shadow-soft); }
.poster { position: relative; height: 150px; padding: 18px 20px; display: flex; flex-direction: column; justify-content: flex-end; color: #fff; }
.poster .month { position: absolute; top: 16px; left: 20px; font-size: 0.72rem; font-weight: 800; letter-spacing: 0.12em; text-transform: uppercase; opacity: 0.85; }
.poster .name { font-family: var(--display); font-weight: 800; font-size: 1.7rem; line-height: 1.05; letter-spacing: -0.02em; }
.poster .check { position: absolute; top: 14px; right: 14px; width: 28px; height: 28px; border-radius: 999px; background: #fff; color: var(--violet); display: grid; place-items: center; }
.fest-body { padding: 14px 18px 16px; display: flex; flex-direction: column; gap: 10px; }
.fest-meta { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; font-size: 0.86rem; color: var(--muted); }
.fest-meta b { color: var(--ink); }
.fest-tags { display: flex; flex-wrap: wrap; gap: 6px; }
.fest-foot { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-top: 4px; }
.also { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; padding: 12px 14px; border-radius: 12px; background: var(--eif-bg); font-size: 0.86rem; }
.dates { display: grid; grid-template-columns: 1fr auto; gap: 20px; align-items: center; margin-top: 24px; padding: 18px 22px; }
.date-row { display: flex; align-items: center; gap: 10px; }
.date-box { display: flex; flex-direction: column; padding: 10px 14px; border: 1px solid var(--line); border-radius: 12px; min-width: 150px; background: #fff; }
.date-box span { font-size: 0.7rem; font-weight: 800; text-transform: uppercase; letter-spacing: 0.05em; color: var(--muted); }
.date-box b { font-size: 1.05rem; }
.strip { display: flex; gap: 3px; }
.strip i { display: block; width: 14px; height: 22px; border-radius: 3px; background: #eef0f5; }
.strip i.on { background: var(--violet); }
.strip i.eif { background: var(--eif); }

content.content:
1	    .toolbar { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; margin-top: 18px; }
2	    .toolbar .search { display: flex; align-items: center; gap: 10px; padding: 10px 14px; border: 1px solid var(--line); border-radius: 12px; background: #fff; color: var(--muted); min-width: 320px; }
3	    .group { margin-top: 22px; }
4	    .group-head { display: flex; align-items: center; gap: 12px; margin-bottom: 10px; }
5	    .group-head h2 { font-family: var(--display); font-size: 1.3rem; margin: 0; letter-spacing: -0.01em; }
6	    .group-head .swatch { width: 12px; height: 26px; border-radius: 4px; }
7	    .group-head .count { color: var(--muted); font-size: 0.9rem; }
8	    .rows { display: flex; flex-direction: column; gap: 8px; }
9	    .row { display: grid; grid-template-columns: 34px 1fr 210px 160px 90px; gap: 14px; align-items: center; padding: 10px 14px; border-radius: 12px; background: #fff; border: 1px solid var(--line); }
10	    .row.is-starred { border-color: #f3d269; background: #fffdf3; }
11	    .row.is-dim { opacity: 0.55; }
12	    .star { width: 34px; height: 34px; border-radius: 999px; display: grid; place-items: center; border: 1px solid var(--line); color: #c2c8d2; }
13	    .row.is-starred .star { background: var(--fr-locked); border-color: #eac247; color: #7a5b00; }
14	    .row .title { font-weight: 700; font-size: 0.95rem; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
15	    .row .sub { font-size: 0.8rem; color: var(--muted); }
16	    .days { display: flex; gap: 3px; }
17	    .days i { display: block; width: 36px; height: 24px; border-radius: 4px; background: #eef0f5; }
18	    .days i.ok { background: #2ac9de; }
19	    .days i.tight { background: #ffce00; }
20	    .days i.sold { background: #e6e9ef; border: 1px dashed #c6cdda; }
