.toolbar { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; margin-top: 18px; }
.toolbar .search { display: flex; align-items: center; gap: 10px; padding: 10px 14px; border: 1px solid var(--line); border-radius: 12px; background: #fff; color: var(--muted); min-width: 320px; }
.group { margin-top: 22px; }
.group-head { display: flex; align-items: center; gap: 12px; margin-bottom: 10px; }
.group-head h2 { font-family: var(--display); font-size: 1.3rem; margin: 0; letter-spacing: -0.01em; }
.group-head .swatch { width: 12px; height: 26px; border-radius: 4px; }
.group-head .count { color: var(--muted); font-size: 0.9rem; }
.rows { display: flex; flex-direction: column; gap: 8px; }
.row { display: grid; grid-template-columns: 34px 1fr 210px 160px 90px; gap: 14px; align-items: center; padding: 10px 14px; border-radius: 12px; background: #fff; border: 1px solid var(--line); }
.row.is-starred { border-color: #f3d269; background: #fffdf3; }
